#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <fstream>
#include <algorithm>

struct Vec3 {
    double x, y, z;
    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(double s) const { return {x * s, y * s, z * s}; }
    double dot(const Vec3& o) const { return x * o.x + y * o.y + z * o.z; }
    double norm_sq() const { return dot(*this); }
    double norm() const { return std::sqrt(norm_sq()); }
};

struct Quat {
    double w, x, y, z;
    Vec3 rotate(const Vec3& v) const {
        // v' = v + 2 * r x (r x v + w * v)
        Vec3 r = {x, y, z};
        Vec3 rxv = {r.y * v.z - r.z * v.y, r.z * v.x - r.x * v.z, r.x * v.y - r.y * v.x};
        Vec3 rxv_wv = {rxv.x + w * v.x, rxv.y + w * v.y, rxv.z + w * v.z};
        Vec3 r_rxv_wv = {r.y * rxv_wv.z - r.z * rxv_wv.y, r.z * rxv_wv.x - r.x * rxv_wv.z, r.x * rxv_wv.y - r.y * rxv_wv.x};
        return {v.x + 2.0 * r_rxv_wv.x, v.y + 2.0 * r_rxv_wv.y, v.z + 2.0 * r_rxv_wv.z};
    }
};

double dist_sq_segment_to_segment(const Vec3& p1, const Vec3& q1, const Vec3& p2, const Vec3& q2) {
    Vec3 d1 = q1 - p1;
    Vec3 d2 = q2 - p2;
    Vec3 r = p1 - p2;
    double a = d1.norm_sq();
    double e = d2.norm_sq();
    double f = d2.dot(r);
    double s, t;
    if (a <= 1e-12 && e <= 1e-12) {
        return r.norm_sq();
    }
    if (a <= 1e-12) {
        s = 0.0;
        t = std::clamp(f / e, 0.0, 1.0);
    } else {
        double c = d1.dot(r);
        if (e <= 1e-12) {
            t = 0.0;
            s = std::clamp(-c / a, 0.0, 1.0);
        } else {
            double b = d1.dot(d2);
            double denom = a * e - b * b;
            if (denom != 0.0) {
                s = std::clamp((b * f - c * e) / denom, 0.0, 1.0);
            } else {
                s = 0.0;
            }
            t = (b * s + f) / e;
            if (t < 0.0) {
                t = 0.0;
                s = std::clamp(-c / a, 0.0, 1.0);
            } else if (t > 1.0) {
                t = 1.0;
                s = std::clamp((b - c) / a, 0.0, 1.0);
            }
        }
    }
    Vec3 c1 = p1 + d1 * s;
    Vec3 c2 = p2 + d2 * t;
    return (c1 - c2).norm_sq();
}

int main() {
    Vec3 p1 = {0, 0, 0}, q1 = {1, 0, 0};
    Vec3 p2 = {0, 1, 0}, q2 = {1, 1, 0};
    std::cout << "Test dist: " << std::sqrt(dist_sq_segment_to_segment(p1, q1, p2, q2)) << std::endl;
    return 0;
}
