            t = 0.0;
            s = std::clamp(-c / a, 0.0, 1.0);
        } else {
            double b = d1.dot(d2);
            double denom = a * e - b * b;
            if (denom != 0.0) s = std::clamp((b * f - c * e) / denom, 0.0, 1.0);
            else s = 0.0;
            t = (b * s + f) / e;
            if (t < 0.0) {
                t = 0.0;
                s = std::clamp(-c / a, 0.0, 1.0);
            } else if (t > 1.0) {
                t = 1.0;
                s = std::clamp((b - c) / a, 0.0, 1.0);
            }
        }
    }
    Vec3 c1 = p1 + d1 * s;
    Vec3 c2 = p2 + d2 * t;
    return (c1 - c2).norm_sq();
}

struct Segment {
    Vec3 p1, p2;
    Vec3 min_pt, max_pt;
};

void update_aabb(Segment& s) {
    s.min_pt = {std::min(s.p1.x, s.p2.x), std::min(s.p1.y, s.p2.y), std::min(s.p1.z, s.p2.z)};
    s.max_pt = {std::max(s.p1.x, s.p2.x), std::max(s.p1.y, s.p2.y), std::max(s.p1.z, s.p2.z)};
}

inline bool aabb_overlap(const Segment& a, const Segment& b, double threshold) {
    if (a.min_pt.x - b.max_pt.x > threshold || b.min_pt.x - a.max_pt.x > threshold) return false;
    if (a.min_pt.y - b.max_pt.y > threshold || b.min_pt.y - a.max_pt.y > threshold) return false;
    if (a.min_pt.z - b.max_pt.z > threshold || b.min_pt.z - a.max_pt.z > threshold) return false;
    return true;
}

std::vector<Segment> segs_a;
std::vector<Vec3> orig_pts_b;
Vec3 p_grasp = {1.2, 0.36, 0.28};
double r_threshold = 0.2133;

double get_clearance(const Vec3& pos, const Quat& q) {
    // Transform B points: p' = q.rotate(p - p_grasp) + p_grasp + pos
    std::vector<Segment> segs_b(orig_pts_b.size() - 1);
    Vec3 prev = q.rotate(orig_pts_b[0] - p_grasp) + p_grasp + pos;
    for (size_t i = 0; i < segs_b.size(); ++i) {
        Vec3 curr = q.rotate(orig_pts_b[i+1] - p_grasp) + p_grasp + pos;
        segs_b[i].p1 = prev;
        segs_b[i].p2 = curr;
        update_aabb(segs_b[i]);
        prev = curr;
    }

    double min_dist_sq = 1e9;
    for (const auto& sa : segs_a) {
        for (const auto& sb : segs_b) {
            if (!aabb_overlap(sa, sb, std::sqrt(min_dist_sq))) continue;
            double d_sq = dist_sq_segment_to_segment(sa.p1, sa.p2, sb.p1, sb.p2);
            if (d_sq < min_dist_sq) {
                min_dist_sq = d_sq;
                if (min_dist_sq < r_threshold * r_threshold) {
                    return std::sqrt(min_dist_sq) - r_threshold;
                }
            }
        }
    }
    return std::sqrt(min_dist_sq) - r_threshold;
}

bool is_goal(const Vec3& pos, const Quat& q) {
    // Check if B can slide away to infinity
    // Find bounds of transformed B
    double min_x = 1e9, max_x = -1e9;
    double min_y = 1e9, max_y = -1e9;
    double min_z = 1e9, max_z = -1e9;
    for (const auto& p : orig_pts_b) {
        Vec3 pt = q.rotate(p - p_grasp) + p_grasp + pos;
        min_x = std::min(min_x, pt.x); max_x = std::max(max_x, pt.x);
        min_y = std::min(min_y, pt.y); max_y = std::max(max_y, pt.y);
        min_z = std::min(min_z, pt.z); max_z = std::max(max_z, pt.z);
    }
    // A bounds: x in [-0.07, 2.35], y in [-0.13, 1.58], z in [-0.18, 0.43]
    if (min_y > 1.60) return true;
    if (max_y < -0.15) return true;
    if (min_x > 2.36) return true;
    if (max_x < -0.08) return true;
    if (min_z > 0.45) return true;
    if (max_z < -0.20) return true;
    return false;
}

