    std::vector<Vec3> pts_a(43);
    orig_pts_b.resize(39);
    std::ifstream fa("/tmp/simp_a.bin", std::ios::binary);
    fa.read(reinterpret_cast<char*>(pts_a.data()), pts_a.size() * sizeof(Vec3));
    std::ifstream fb("/tmp/simp_b.bin", std::ios::binary);
    fb.read(reinterpret_cast<char*>(orig_pts_b.data()), orig_pts_b.size() * sizeof(Vec3));

    segs_a.resize(pts_a.size() - 1);
    for (size_t i = 0; i < segs_a.size(); ++i) {
        segs_a[i].p1 = pts_a[i];
        segs_a[i].p2 = pts_a[i+1];
        update_aabb(segs_a[i]);
    }

    Vec3 pos0 = {0, 0, 0};
    Quat q0 = {1, 0, 0, 0};
    std::cout << "Start clearance: " << get_clearance(pos0, q0) << std::endl;
    std::cout << "Start is_goal: " << is_goal(pos0, q0) << std::endl;

    return 0;
