    for (const auto& sa : segs_a) {
        for (const auto& sb : segs_b) {
            if (!aabb_overlap(sa, sb, limit)) continue;
            double d_sq = dist_sq_segment_to_segment(sa.p1, sa.p2, sb.p1, sb.p2);
            if (d_sq < limit_sq) {
