    std::ifstream fa("/tmp/simp_a.bin", std::ios::binary);
    fa.read(reinterpret_cast<char*>(pts_a.data()), pts_a.size() * sizeof(Vec3));
    std::ifstream fb("/tmp/simp_b.bin", std::ios::binary);
    fb.read(reinterpret_cast<char*>(orig_pts_b.data()), orig_pts_b.size() * sizeof(Vec3));

    segs_a.resize(pts_a.size() - 1);
    for (size_t i = 0; i < segs_a.size(); ++i) {
        segs_a[i].p1 = pts_a[i];
        segs_a[i].p2 = pts_a[i+1];
        update_aabb(segs_a[i]);
    }

    std::vector<Node> tree;
    tree.push_back({{0, 0, 0}, Quat::identity(), -1});

    std::mt19937_64 rng(42);
    // Workspace bounds for pos: [-0.8, 1.5]
    std::uniform_real_distribution<double> dist_x(-0.8, 1.5);
    std::uniform_real_distribution<double> dist_y(-0.8, 2.0);
    std::uniform_real_distribution<double> dist_z(-0.8, 1.5);
    std::normal_distribution<double> dist_norm(0.0, 1.0);

    auto random_quat = [&]() -> Quat {
        Quat q = {dist_norm(rng), dist_norm(rng), dist_norm(rng), dist_norm(rng)};
        q.normalize();
        return q;
    };

    auto t0 = std::chrono::high_resolution_clock::now();
    int goal_idx = -1;

    for (int iter = 0; iter < 100000; ++iter) {
        Vec3 target_pos = {dist_x(rng), dist_y(rng), dist_z(rng)};
        Quat target_q = random_quat();

        // Find nearest node
        // Metric: dist_pos + 0.5 * angle
        int best_i = 0;
        double best_dist = 1e9;
        for (int i = 0; i < (int)tree.size(); ++i) {
            double dp = (tree[i].pos - target_pos).norm();
            double dq = tree[i].q.angle_to(target_q);
            double d = dp + 0.3 * dq;
            if (d < best_dist) {
                best_dist = d;
                best_i = i;
            }
        }

        // Steer from tree[best_i] towards target
        const Node& near_node = tree[best_i];
        Vec3 diff_pos = target_pos - near_node.pos;
        double norm_dp = diff_pos.norm();
        double step_pos = 0.04;
        Vec3 new_pos = (norm_dp <= step_pos) ? target_pos : (near_node.pos + diff_pos * (step_pos / norm_dp));

        double angle = near_node.q.angle_to(target_q);
        double step_rot = 0.08;
        Quat new_q = (angle <= step_rot) ? target_q : Quat::slerp(near_node.q, target_q, step_rot / angle);

        // Check edge validity
        Vec3 mid_pos = (near_node.pos + new_pos) * 0.5;
        Quat mid_q = Quat::slerp(near_node.q, new_q, 0.5);

        if (is_collision_free(mid_pos, mid_q) && is_collision_free(new_pos, new_q)) {
            int new_idx = tree.size();
            tree.push_back({new_pos, new_q, best_i});

            if (can_slide_to_infinity(new_pos, new_q)) {
                goal_idx = new_idx;
                std::cout << "Found goal at iteration " << iter << "! Tree size: " << tree.size() << std::endl;
                break;
            }
        }

        if (iter % 10000 == 0 && iter > 0) {
            auto t1 = std::chrono::high_resolution_clock::now();
            double sec = std::chrono::duration<double>(t1 - t0).count();
            std::cout << "Iter " << iter << ", tree size: " << tree.size() << ", elapsed: " << sec << " s" << std::endl;
        }
    }

    if (goal_idx == -1) {
        std::cout << "Goal not found in 100,000 iterations." << std::endl;
    }

    return 0;
}
