    fa.read(reinterpret_cast<char*>(pts_a.data()), pts_a.size() * sizeof(Vec3));
    std::ifstream fb("/tmp/simp_b.bin", std::ios::binary);
    fb.read(reinterpret_cast<char*>(orig_pts_b.data()), orig_pts_b.size() * sizeof(Vec3));

    segs_a.resize(pts_a.size() - 1);
    for (size_t i = 0; i < segs_a.size(); ++i) {
        segs_a[i].p1 = pts_a[i];
        segs_a[i].p2 = pts_a[i+1];
        update_aabb(segs_a[i]);
    }

    std::vector<Node> tree;
    tree.push_back({{0, 0, 0}, Quat::identity(), -1, 0, 1.0});

    std::mt19937_64 rng(42);
    std::normal_distribution<double> dist_norm(0.0, 1.0);
    std::uniform_real_distribution<double> dist_uni(0.0, 1.0);

    auto random_unit_vec = [&]() -> Vec3 {
        Vec3 v = {dist_norm(rng), dist_norm(rng), dist_norm(rng)};
        double n = v.norm();
        return (n > 1e-6) ? (v * (1.0 / n)) : Vec3{1, 0, 0};
    };

    auto t0 = std::chrono::high_resolution_clock::now();
    int goal_idx = -1;

    for (int iter = 0; iter < 500000; ++iter) {
        // Sample node inversely proportional to degree/weight
        // Reservoir / roulette sampling
        int pick = 0;
        // Fast selection: sample random candidate, accept with prob 1 / (1 + num_children)
        for (int retry = 0; retry < 10; ++retry) {
            int cand = rng() % tree.size();
            double prob = 1.0 / (1.0 + tree[cand].num_children);
            if (dist_uni(rng) < prob) {
                pick = cand;
                break;
            }
        }

        const Node& base = tree[pick];

        // Sample small perturbation
        // Step size: pos ~ 0.02 - 0.06 m, rot ~ 0.05 - 0.15 rad
        double step_p = 0.01 + 0.05 * dist_uni(rng);
        Vec3 dir_p = random_unit_vec();
        Vec3 new_pos = base.pos + dir_p * step_p;

        double step_r = 0.02 + 0.10 * dist_uni(rng);
        Vec3 axis_r = random_unit_vec();
        Quat rot = Quat::from_axis_angle(axis_r, step_r);
        Quat new_q = rot * base.q;
        new_q.normalize();

        // Check mid and endpoint
        Vec3 mid_pos = (base.pos + new_pos) * 0.5;
        Quat mid_q = Quat::slerp(base.q, new_q, 0.5);

        if (is_collision_free(mid_pos, mid_q) && is_collision_free(new_pos, new_q)) {
