        }

        if (iter % 50000 == 0 && iter > 0) {
            auto t1 = std::chrono::high_resolution_clock::now();
            double sec = std::chrono::duration<double>(t1 - t0).count();
            std::cout << "Iter " << iter << ", tree: " << tree.size() << ", elapsed: " << sec << " s" << std::endl;
        }
    }

    if (goal_idx != -1) {
        // Backtrack path
        std::vector<int> path_indices;
        int curr = goal_idx;
        while (curr != -1) {
            path_indices.push_back(curr);
            curr = tree[curr].parent;
        }
        std::reverse(path_indices.begin(), path_indices.end());
        std::cout << "Path length: " << path_indices.size() << " waypoints" << std::endl;

        std::ofstream out("/tmp/solution_path.txt");
        for (int idx : path_indices) {
