                << tree[idx].q.w << " " << tree[idx].q.x << " " << tree[idx].q.y << " " << tree[idx].q.z << "\n";
        }
        std::cout << "Wrote /tmp/solution_path.txt" << std::endl;
    } else {
        std::cout << "Goal not found." << std::endl;
    }

    return 0;
}
