            auto t1 = std::chrono::high_resolution_clock::now();
            double sec = std::chrono::duration<double>(t1 - t0).count();
            std::cout << "Iter " << iter << ", start tree: " << tree_start.size() 
                      << ", goal tree: " << tree_goal.size() << ", elapsed: " << sec << " s" << std::endl;
        }
    }

    if (connect_s != -1) {
        std::cout << "SUCCESSFULLY CONNECTED START AND GOAL!" << std::endl;
    } else {
        std::cout << "Not connected in 100k iters." << std::endl;
    }

    return 0;
}
