    Quat goal_q = Quat::from_euler(1.00, 0.903, 0.355);

    std::vector<Node> tree_start, tree_goal;
    tree_start.push_back({start_pos, start_q, -1});
    tree_goal.push_back({goal_pos, goal_q, -1});

    std::mt19937_64 rng(42);
    std::uniform_real_distribution<double> dist_x(-0.4, 0.4);
    std::uniform_real_distribution<double> dist_y(0.0, 0.7);
    std::uniform_real_distribution<double> dist_z(-0.2, 0.4);
    std::normal_distribution<double> dist_norm(0.0, 1.0);

    auto random_quat = [&]() -> Quat {
        Quat q = {dist_norm(rng), dist_norm(rng), dist_norm(rng), dist_norm(rng)};
        q.normalize();
        return q;
    };

    auto extend = [&](std::vector<Node>& tr, const Vec3& target_p, const Quat& target_q, int& reached_idx) -> int {
        // Find nearest
        int best_i = 0;
        double best_d = 1e9;
        for (int i = 0; i < (int)tr.size(); ++i) {
            double d = (tr[i].pos - target_p).norm() + 0.3 * tr[i].q.angle_to(target_q);
            if (d < best_d) { best_d = d; best_i = i; }
        }

        const Node& near_n = tr[best_i];
        Vec3 dp = target_p - near_n.pos;
        double ndp = dp.norm();
        double step_p = 0.03;
        Vec3 new_p = (ndp <= step_p) ? target_p : (near_n.pos + dp * (step_p / ndp));

        double da = near_n.q.angle_to(target_q);
        double step_r = 0.06;
        Quat new_q = (da <= step_r) ? target_q : Quat::slerp(near_n.q, target_q, step_r / da);

        if (is_collision_free((near_n.pos + new_p) * 0.5, Quat::slerp(near_n.q, new_q, 0.5)) &&
            is_collision_free(new_p, new_q)) {
            int new_idx = tr.size();
            tr.push_back({new_p, new_q, best_i});
            reached_idx = new_idx;
            if ((new_p - target_p).norm() < 1e-4 && new_q.angle_to(target_q) < 1e-3) {
                return 1; // REACHED
            }
            return 2; // ADVANCED
        }
        return 0; // TRAPPED
    };

    auto t0 = std::chrono::high_resolution_clock::now();
    int conn_idx_a = -1, conn_idx_b = -1;
    bool swapped = false;

    for (int iter = 0; iter < 100000; ++iter) {
        Vec3 q_rand_p = {dist_x(rng), dist_y(rng), dist_z(rng)};
        Quat q_rand_q = random_quat();

        int new_idx_a = -1;
        if (extend(tree_start, q_rand_p, q_rand_q, new_idx_a) != 0) {
            // Now tree_goal tries to CONNECT to tree_start[new_idx_a]
            Vec3 target_p = tree_start[new_idx_a].pos;
            Quat target_q = tree_start[new_idx_a].q;

            int new_idx_b = -1;
            while (true) {
                int status = extend(tree_goal, target_p, target_q, new_idx_b);
                if (status == 1) { // REACHED! CONNECTED!
                    conn_idx_a = new_idx_a;
                    conn_idx_b = new_idx_b;
                    break;
                }
                if (status == 0) break; // Trapped
            }

            if (conn_idx_a != -1) {
                std::cout << "SUCCESSFULLY CONNECTED at iteration " << iter << "!" << std::endl;
                std::cout << "Tree A size: " << tree_start.size() << ", Tree B size: " << tree_goal.size() << std::endl;
                break;
            }
        }

        std::swap(tree_start, tree_goal);
        swapped = !swapped;

        if (iter % 10000 == 0 && iter > 0) {
            auto t1 = std::chrono::high_resolution_clock::now();
            double sec = std::chrono::duration<double>(t1 - t0).count();
            std::cout << "Iter " << iter << ", tree A: " << tree_start.size() 
                      << ", tree B: " << tree_goal.size() << ", elapsed: " << sec << " s" << std::endl;
        }
    }

    if (conn_idx_a != -1) {
        std::cout << "Connected! Swapped = " << swapped << std::endl;
        auto& t_start = swapped ? tree_goal : tree_start;
        auto& t_goal  = swapped ? tree_start : tree_goal;
        int idx_s = swapped ? conn_idx_b : conn_idx_a;
        int idx_g = swapped ? conn_idx_a : conn_idx_b;

        std::vector<Node> path;
        int c = idx_s;
        while (c != -1) {
            path.push_back(t_start[c]);
            c = t_start[c].parent;
        }
        std::reverse(path.begin(), path.end());

        c = t_goal[idx_g].parent; // don't duplicate meeting node
        while (c != -1) {
            path.push_back(t_goal[c]);
            c = t_goal[c].parent;
        }

        std::cout << "Total path length: " << path.size() << " waypoints" << std::endl;
        std::ofstream out("/tmp/rrt_connect_path.txt");
        for (const auto& n : path) {
            out << n.pos.x << " " << n.pos.y << " " << n.pos.z << " "
                << n.q.w << " " << n.q.x << " " << n.q.y << " " << n.q.z << "\n";
        }
        std::cout << "Wrote /tmp/rrt_connect_path.txt" << std::endl;
    } else {
        std::cout << "Did not connect in 100k iterations." << std::endl;
    }

    return 0;
}
