#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <fstream>
#include <algorithm>
#include <random>

struct Vec3 {
    double x, y, z;
    Vec3 operator+(const Vec3& o) const { return {x + o.x, y + o.y, z + o.z}; }
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(double s) const { return {x * s, y * s, z * s}; }
    double dot(const Vec3& o) const { return x * o.x + y * o.y + z * o.z; }
    double norm_sq() const { return dot(*this); }
    double norm() const { return std::sqrt(norm_sq()); }
};

struct Quat {
    double w, x, y, z;
    static Quat identity() { return {1, 0, 0, 0}; }
    static Quat from_euler(double roll, double pitch, double yaw) {
        double cr = std::cos(roll * 0.5), sr = std::sin(roll * 0.5);
        double cp = std::cos(pitch * 0.5), sp = std::sin(pitch * 0.5);
        double cy = std::cos(yaw * 0.5), sy = std::sin(yaw * 0.5);
        return {
            cr * cp * cy + sr * sp * sy,
            sr * cp * cy - cr * sp * sy,
            cr * cp * cy + sr * cp * sy,
            cr * cp * sy - sr * sp * cy
        };
    }
    Vec3 rotate(const Vec3& v) const {
        Vec3 r = {x, y, z};
        Vec3 rxv = {r.y * v.z - r.z * v.y, r.z * v.x - r.x * v.z, r.x * v.y - r.y * v.x};
        Vec3 rxv_wv = {rxv.x + w * v.x, rxv.y + w * v.y, rxv.z + w * v.z};
        Vec3 r_rxv_wv = {r.y * rxv_wv.z - r.z * rxv_wv.y, r.z * rxv_wv.x - r.x * rxv_wv.z, r.x * rxv_wv.y - r.y * rxv_wv.x};
        return {v.x + 2.0 * r_rxv_wv.x, v.y + 2.0 * r_rxv_wv.y, v.z + 2.0 * r_rxv_wv.z};
    }
    Quat operator*(const Quat& q) const {
        return {
            w * q.w - x * q.x - y * q.y - z * q.z,
            w * q.x + x * q.w + y * q.z - z * q.y,
            w * q.y - x * q.z + y * q.w + z * q.x,
            w * q.z + x * q.y - y * q.x + z * q.w
        };
    }
    void normalize() {
        double n = std::sqrt(w*w + x*x + y*y + z*z);
        if (n > 1e-12) { w /= n; x /= n; y /= n; z /= n; }
    }
    static Quat slerp(const Quat& q1, const Quat& q2, double t) {
        double dot = q1.w * q2.w + q1.x * q2.x + q1.y * q2.y + q1.z * q2.z;
        Quat q2_mod = q2;
        if (dot < 0.0) {
            dot = -dot;
            q2_mod = {-q2.w, -q2.x, -q2.y, -q2.z};
        }
        if (dot > 0.9995) {
            Quat r = {
                q1.w + t * (q2_mod.w - q1.w),
                q1.x + t * (q2_mod.x - q1.x),
                q1.y + t * (q2_mod.y - q1.y),
                q1.z + t * (q2_mod.z - q1.z)
            };
            r.normalize();
            return r;
        }
        double theta = std::acos(dot);
        double sin_theta = std::sin(theta);
        double s1 = std::sin((1.0 - t) * theta) / sin_theta;
        double s2 = std::sin(t * theta) / sin_theta;
        return {
            s1 * q1.w + s2 * q2_mod.w,
            s1 * q1.x + s2 * q2_mod.x,
            s1 * q1.y + s2 * q2_mod.y,
            s1 * q1.z + s2 * q2_mod.z
        };
    }
    double angle_to(const Quat& o) const {
        double dot = std::abs(w * o.w + x * o.x + y * o.y + z * o.z);
        if (dot > 1.0) dot = 1.0;
        return 2.0 * std::acos(dot);
    }
};

double dist_sq_segment_to_segment(const Vec3& p1, const Vec3& q1, const Vec3& p2, const Vec3& q2) {
    Vec3 d1 = q1 - p1;
    Vec3 d2 = q2 - p2;
    Vec3 r = p1 - p2;
    double a = d1.norm_sq();
    double e = d2.norm_sq();
    double f = d2.dot(r);
    double s, t;
    if (a <= 1e-12 && e <= 1e-12) return r.norm_sq();
    if (a <= 1e-12) {
        s = 0.0;
        t = std::clamp(f / e, 0.0, 1.0);
    } else {
        double c = d1.dot(r);
        if (e <= 1e-12) {
            t = 0.0;
            s = std::clamp(-c / a, 0.0, 1.0);
        } else {
            double b = d1.dot(d2);
            double denom = a * e - b * b;
            if (denom != 0.0) s = std::clamp((b * f - c * e) / denom, 0.0, 1.0);
            else s = 0.0;
            t = (b * s + f) / e;
            if (t < 0.0) {
                t = 0.0;
                s = std::clamp(-c / a, 0.0, 1.0);
            } else if (t > 1.0) {
                t = 1.0;
                s = std::clamp((b - c) / a, 0.0, 1.0);
            }
        }
    }
    Vec3 c1 = p1 + d1 * s;
    Vec3 c2 = p2 + d2 * t;
    return (c1 - c2).norm_sq();
}

struct Segment {
    Vec3 p1, p2;
    Vec3 min_pt, max_pt;
};

void update_aabb(Segment& s) {
    s.min_pt = {std::min(s.p1.x, s.p2.x), std::min(s.p1.y, s.p2.y), std::min(s.p1.z, s.p2.z)};
    s.max_pt = {std::max(s.p1.x, s.p2.x), std::max(s.p1.y, s.p2.y), std::max(s.p1.z, s.p2.z)};
}

inline bool aabb_overlap(const Segment& a, const Segment& b, double threshold) {
    if (a.min_pt.x - b.max_pt.x > threshold || b.min_pt.x - a.max_pt.x > threshold) return false;
    if (a.min_pt.y - b.max_pt.y > threshold || b.min_pt.y - a.max_pt.y > threshold) return false;
    if (a.min_pt.z - b.max_pt.z > threshold || b.min_pt.z - a.max_pt.z > threshold) return false;
    return true;
}

std::vector<Segment> segs_a;
std::vector<Vec3> orig_pts_b;
Vec3 p_grasp = {1.2, 0.36, 0.28};
double r_threshold = 0.2133;

bool is_collision_free(const Vec3& pos, const Quat& q, double safety_margin = 0.005) {
    double limit = r_threshold + safety_margin;
    double limit_sq = limit * limit;
    std::vector<Segment> segs_b(orig_pts_b.size() - 1);
    Vec3 prev = q.rotate(orig_pts_b[0] - p_grasp) + p_grasp + pos;
    for (size_t i = 0; i < segs_b.size(); ++i) {
        Vec3 curr = q.rotate(orig_pts_b[i+1] - p_grasp) + p_grasp + pos;
        segs_b[i].p1 = prev;
        segs_b[i].p2 = curr;
        update_aabb(segs_b[i]);
        prev = curr;
    }

    for (const auto& sa : segs_a) {
        for (const auto& sb : segs_b) {
            if (!aabb_overlap(sa, sb, limit)) continue;
            double d_sq = dist_sq_segment_to_segment(sa.p1, sa.p2, sb.p1, sb.p2);
            if (d_sq < limit_sq) {
                return false;
            }
        }
    }
    return true;
}

struct Node {
