    if (a.min_pt.y - b.max_pt.y > threshold || b.min_pt.y - a.max_pt.y > threshold) return false;
    if (a.min_pt.z - b.max_pt.z > threshold || b.min_pt.z - a.max_pt.z > threshold) return false;
