        segs_a[i].p1 = pts_a[i];
        segs_a[i].p2 = pts_a[i+1];
        update_aabb(segs_a[i]);
    }

    // State 1: at dy = 0.70
    Vec3 s1_pos = {-0.038, 0.70, 0.368};
    Quat s1_q = Quat::from_euler(-2.250, -0.842, 1.111);

    // State 2: at dy = 0.88
    Vec3 s2_pos = {-0.120, 0.88, 0.458};
    Quat s2_q = Quat::from_euler(-2.501, -1.700, 1.352);

    std::cout << "S1 free: " << is_collision_free(s1_pos, s1_q) << std::endl;
    std::cout << "S2 free: " << is_collision_free(s2_pos, s2_q) << std::endl;

    std::vector<Node> tree_a, tree_b;
    tree_a.push_back({s1_pos, s1_q, -1});
    tree_b.push_back({s2_pos, s2_q, -1});

    std::mt19937_64 rng(42);
    std::uniform_real_distribution<double> dist_x(-0.30, 0.10);
    std::uniform_real_distribution<double> dist_y(0.60, 1.00);
    std::uniform_real_distribution<double> dist_z(0.25, 0.55);
    std::uniform_real_distribution<double> dist_roll(-2.8, -2.0);
    std::uniform_real_distribution<double> dist_pitch(-1.9, -0.6);
    std::uniform_real_distribution<double> dist_yaw(0.9, 1.7);

    auto extend = [&](std::vector<Node>& tr, const Vec3& target_p, const Quat& target_q, int& reached_idx) -> int {
        int best_i = 0;
        double best_d = 1e9;
        for (int i = 0; i < (int)tr.size(); ++i) {
            double d = (tr[i].pos - target_p).norm() + 0.3 * tr[i].q.angle_to(target_q);
            if (d < best_d) { best_d = d; best_i = i; }
        }

        const Node& near_n = tr[best_i];
        Vec3 dp = target_p - near_n.pos;
        double ndp = dp.norm();
        double step_p = 0.02;
        Vec3 new_p = (ndp <= step_p) ? target_p : (near_n.pos + dp * (step_p / ndp));

        double da = near_n.q.angle_to(target_q);
        double step_r = 0.04;
        Quat new_q = (da <= step_r) ? target_q : Quat::slerp(near_n.q, target_q, step_r / da);

        if (is_collision_free((near_n.pos + new_p) * 0.5, Quat::slerp(near_n.q, new_q, 0.5)) &&
            is_collision_free(new_p, new_q)) {
            int new_idx = tr.size();
            tr.push_back({new_p, new_q, best_i});
            reached_idx = new_idx;
            if ((new_p - target_p).norm() < 1e-4 && new_q.angle_to(target_q) < 1e-3) {
                return 1;
            }
            return 2;
        }
        return 0;
    };

    int conn_a = -1, conn_b = -1;
    bool swapped = false;

    for (int iter = 0; iter < 100000; ++iter) {
        Vec3 q_rand_p = {dist_x(rng), dist_y(rng), dist_z(rng)};
        Quat q_rand_q = Quat::from_euler(dist_roll(rng), dist_pitch(rng), dist_yaw(rng));

        int new_idx_a = -1;
        if (extend(tree_a, q_rand_p, q_rand_q, new_idx_a) != 0) {
            Vec3 target_p = tree_a[new_idx_a].pos;
            Quat target_q = tree_a[new_idx_a].q;

            int new_idx_b = -1;
            while (true) {
                int status = extend(tree_b, target_p, target_q, new_idx_b);
                if (status == 1) {
                    conn_a = new_idx_a;
                    conn_b = new_idx_b;
                    break;
                }
                if (status == 0) break;
            }

            if (conn_a != -1) {
                std::cout << "SUCCESSFULLY CONNECTED at iteration " << iter << "!" << std::endl;
                std::cout << "Tree A: " << tree_a.size() << ", Tree B: " << tree_b.size() << std::endl;
                break;
            }
        }

        std::swap(tree_a, tree_b);
        swapped = !swapped;
    }

    if (conn_a != -1) {
        auto& t_start = swapped ? tree_b : tree_a;
        auto& t_goal  = swapped ? tree_a : tree_b;
        int idx_s = swapped ? conn_b : conn_a;
        int idx_g = swapped ? conn_a : conn_b;

        std::vector<Node> bridge;
        int c = idx_s;
        while (c != -1) {
            bridge.push_back(t_start[c]);
            c = t_start[c].parent;
        }
        std::reverse(bridge.begin(), bridge.end());

        c = t_goal[idx_g].parent;
        while (c != -1) {
            bridge.push_back(t_goal[c]);
            c = t_goal[c].parent;
        }

        std::cout << "Bridge length: " << bridge.size() << " waypoints" << std::endl;
        std::ofstream out("/tmp/bridge_path.txt");
        for (const auto& n : bridge) {
            out << n.pos.x << " " << n.pos.y << " " << n.pos.z << " "
                << n.q.w << " " << n.q.x << " " << n.q.y << " " << n.q.z << "\n";
        }
        std::cout << "Wrote /tmp/bridge_path.txt" << std::endl;
    } else {
        std::cout << "Could not connect s1 and s2 in 100k iterations." << std::endl;
    }

    return 0;
}
