double r_threshold = 0.2133;

bool is_collision_free(const Vec3& pos, const Quat& q, double safety_margin = 0.005) {
    double limit = r_threshold + safety_margin;
    double limit_sq = limit * limit;
    std::vector<Segment> segs_b(orig_pts_b.size() - 1);
    Vec3 prev = q.rotate(orig_pts_b[0] - p_grasp) + p_grasp + pos;
    for (size_t i = 0; i < segs_b.size(); ++i) {
        Vec3 curr = q.rotate(orig_pts_b[i+1] - p_grasp) + p_grasp + pos;
        segs_b[i].p1 = prev;
        segs_b[i].p2 = curr;
        update_aabb(segs_b[i]);
        prev = curr;
    }

    for (const auto& sa : segs_a) {
        for (const auto& sb : segs_b) {
            if (!aabb_overlap(sa, sb, limit)) continue;
            double d_sq = dist_sq_segment_to_segment(sa.p1, sa.p2, sb.p1, sb.p2);
            if (d_sq < limit_sq) {
                return false;
            }
        }
    }
    return true;
}

