struct Quat {
    double w, x, y, z;
    static Quat identity() { return {1, 0, 0, 0}; }
    static Quat from_euler(double roll, double pitch, double yaw) {
        double cr = std::cos(roll * 0.5), sr = std::sin(roll * 0.5);
        double cp = std::cos(pitch * 0.5), sp = std::sin(pitch * 0.5);
        double cy = std::cos(yaw * 0.5), sy = std::sin(yaw * 0.5);
        return {
            cr * cp * cy + sr * sp * sy,
            sr * cp * cy - cr * sp * sy,
            cr * sp * cy + sr * cp * sy,
            cr * cp * sy - sr * sp * cy
        };
    }
    Vec3 rotate(const Vec3& v) const {
        Vec3 r = {x, y, z};
        Vec3 rxv = {r.y * v.z - r.z * v.y, r.z * v.x - r.x * v.z, r.x * v.y - r.y * v.x};
        Vec3 rxv_wv = {rxv.x + w * v.x, rxv.y + w * v.y, rxv.z + w * v.z};
        Vec3 r_rxv_wv = {r.y * rxv_wv.z - r.z * rxv_wv.y, r.z * rxv_wv.x - r.x * rxv_wv.z, r.x * rxv_wv.y - r.y * rxv_wv.x};
