        return {v.x + 2.0 * r_rxv_wv.x, v.y + 2.0 * r_rxv_wv.y, v.z + 2.0 * r_rxv_wv.z};
    }
    Quat operator*(const Quat& q) const {
        return {
            w * q.w - x * q.x - y * q.y - z * q.z,
            w * q.x + x * q.w + y * q.z - z * q.y,
            w * q.y - x * q.z + y * q.w + z * q.x,
            w * q.z + x * q.y - y * q.x + z * q.w
        };
    }
    void normalize() {
        double n = std::sqrt(w*w + x*x + y*y + z*z);
        if (n > 1e-12) { w /= n; x /= n; y /= n; z /= n; }
    }
    static Quat slerp(const Quat& q1, const Quat& q2, double t) {
        double dot = q1.w * q2.w + q1.x * q2.x + q1.y * q2.y + q1.z * q2.z;
        Quat q2_mod = q2;
        if (dot < 0.0) {
            dot = -dot;
            q2_mod = {-q2.w, -q2.x, -q2.y, -q2.z};
        }
        if (dot > 0.9995) {
            Quat r = {
                q1.w + t * (q2_mod.w - q1.w),
                q1.x + t * (q2_mod.x - q1.x),
                q1.y + t * (q2_mod.y - q1.y),
                q1.z + t * (q2_mod.z - q1.z)
            };
            r.normalize();
            return r;
        }
        double theta = std::acos(dot);
        double sin_theta = std::sin(theta);
        double s1 = std::sin((1.0 - t) * theta) / sin_theta;
        double s2 = std::sin(t * theta) / sin_theta;
        return {
            s1 * q1.w + s2 * q2_mod.w,
            s1 * q1.x + s2 * q2_mod.x,
            s1 * q1.y + s2 * q2_mod.y,
            s1 * q1.z + s2 * q2_mod.z
        };
    }
    double angle_to(const Quat& o) const {
        double dot = std::abs(w * o.w + x * o.x + y * o.y + z * o.z);
        if (dot > 1.0) dot = 1.0;
        return 2.0 * std::acos(dot);
    }
};

double dist_sq_segment_to_segment(const Vec3& p1, const Vec3& q1, const Vec3& p2, const Vec3& q2) {
    Vec3 d1 = q1 - p1;
    Vec3 d2 = q2 - p2;
    Vec3 r = p1 - p2;
    double a = d1.norm_sq();
    double e = d2.norm_sq();
    double f = d2.dot(r);
    double s, t;
    if (a <= 1e-12 && e <= 1e-12) return r.norm_sq();
    if (a <= 1e-12) {
        s = 0.0;
        t = std::clamp(f / e, 0.0, 1.0);
    } else {
        double c = d1.dot(r);
        if (e <= 1e-12) {
            t = 0.0;
            s = std::clamp(-c / a, 0.0, 1.0);
        } else {
            double b = d1.dot(d2);
            double denom = a * e - b * b;
            if (denom != 0.0) s = std::clamp((b * f - c * e) / denom, 0.0, 1.0);
            else s = 0.0;
            t = (b * s + f) / e;
            if (t < 0.0) {
                t = 0.0;
                s = std::clamp(-c / a, 0.0, 1.0);
            } else if (t > 1.0) {
                t = 1.0;
                s = std::clamp((b - c) / a, 0.0, 1.0);
            }
        }
    }
    Vec3 c1 = p1 + d1 * s;
    Vec3 c2 = p2 + d2 * t;
    return (c1 - c2).norm_sq();
}

struct Segment {
    Vec3 p1, p2;
    Vec3 min_pt, max_pt;
};

void update_aabb(Segment& s) {
    s.min_pt = {std::min(s.p1.x, s.p2.x), std::min(s.p1.y, s.p2.y), std::min(s.p1.z, s.p2.z)};
    s.max_pt = {std::max(s.p1.x, s.p2.x), std::max(s.p1.y, s.p2.y), std::max(s.p1.z, s.p2.z)};
}

inline bool aabb_overlap(const Segment& a, const Segment& b, double threshold) {
    if (a.min_pt.x - b.max_pt.x > threshold || b.min_pt.x - a.max_pt.x > threshold) return false;
    if (a.min_pt.y - b.max_pt.y > threshold || b.min_pt.y - a.max_pt.y > threshold) return false;
    if (a.min_pt.z - b.max_pt.z > threshold || b.min_pt.z - a.max_pt.z > threshold) return false;
    return true;
}

std::vector<Segment> segs_a;
std::vector<Vec3> orig_pts_b;
Vec3 p_grasp = {1.2, 0.36, 0.28};
double r_threshold = 0.2133;

bool is_collision_free(const Vec3& pos, const Quat& q, double safety_margin = 0.005) {
    double limit = r_threshold + safety_margin;
    double limit_sq = limit * limit;
    std::vector<Segment> segs_b(orig_pts_b.size() - 1);
    Vec3 prev = q.rotate(orig_pts_b[0] - p_grasp) + p_grasp + pos;
    for (size_t i = 0; i < segs_b.size(); ++i) {
        Vec3 curr = q.rotate(orig_pts_b[i+1] - p_grasp) + p_grasp + pos;
        segs_b[i].p1 = prev;
        segs_b[i].p2 = curr;
        update_aabb(segs_b[i]);
        prev = curr;
    }

    for (const auto& sa : segs_a) {
        for (const auto& sb : segs_b) {
            if (!aabb_overlap(sa, sb, limit)) continue;
            double d_sq = dist_sq_segment_to_segment(sa.p1, sa.p2, sb.p1, sb.p2);
            if (d_sq < limit_sq) {
                return false;
            }
        }
    }
    return true;
}

struct Node {
    Vec3 pos;
    Quat q;
    int parent;
};

int main() {
    std::vector<Vec3> pts_a(43);
    orig_pts_b.resize(39);
    std::ifstream fa("/tmp/simp_a.bin", std::ios::binary);
    fa.read(reinterpret_cast<char*>(pts_a.data()), pts_a.size() * sizeof(Vec3));
    std::ifstream fb("/tmp/simp_b.bin", std::ios::binary);
    fb.read(reinterpret_cast<char*>(orig_pts_b.data()), orig_pts_b.size() * sizeof(Vec3));

    segs_a.resize(pts_a.size() - 1);
    for (size_t i = 0; i < segs_a.size(); ++i) {
        segs_a[i].p1 = pts_a[i];
        segs_a[i].p2 = pts_a[i+1];
        update_aabb(segs_a[i]);
    }

    Vec3 s1_pos = {-0.041, 0.60, 0.383};
    Quat s1_q = Quat::from_euler(-2.195, -0.927, 1.077);

    Vec3 s2_pos = {0.100, 0.60, 0.200};
    Quat s2_q = Quat::from_euler(1.000, 0.903, 0.355);

    std::cout << "S1 free: " << is_collision_free(s1_pos, s1_q) << std::endl;
    std::cout << "S2 free: " << is_collision_free(s2_pos, s2_q) << std::endl;

    std::vector<Node> tree_a, tree_b;
    tree_a.push_back({s1_pos, s1_q, -1});
    tree_b.push_back({s2_pos, s2_q, -1});

    std::mt19937_64 rng(42);
    std::uniform_real_distribution<double> dist_x(-0.25, 0.25);
    std::uniform_real_distribution<double> dist_y(0.50, 0.70); // allow small dy freedom around 0.60!
    std::uniform_real_distribution<double> dist_z(0.10, 0.50);
    std::normal_distribution<double> dist_norm(0.0, 1.0);

    auto random_quat = [&]() -> Quat {
        Quat q = {dist_norm(rng), dist_norm(rng), dist_norm(rng), dist_norm(rng)};
        q.normalize();
        return q;
    };

    auto extend = [&](std::vector<Node>& tr, const Vec3& target_p, const Quat& target_q, int& reached_idx) -> int {
        int best_i = 0;
        double best_d = 1e9;
        for (int i = 0; i < (int)tr.size(); ++i) {
            double d = (tr[i].pos - target_p).norm() + 0.3 * tr[i].q.angle_to(target_q);
            if (d < best_d) { best_d = d; best_i = i; }
        }

        const Node& near_n = tr[best_i];
        Vec3 dp = target_p - near_n.pos;
        double ndp = dp.norm();
        double step_p = 0.02;
        Vec3 new_p = (ndp <= step_p) ? target_p : (near_n.pos + dp * (step_p / ndp));

        double da = near_n.q.angle_to(target_q);
        double step_r = 0.04;
        Quat new_q = (da <= step_r) ? target_q : Quat::slerp(near_n.q, target_q, step_r / da);

        if (is_collision_free((near_n.pos + new_p) * 0.5, Quat::slerp(near_n.q, new_q, 0.5)) &&
            is_collision_free(new_p, new_q)) {
            int new_idx = tr.size();
            tr.push_back({new_p, new_q, best_i});
            reached_idx = new_idx;
            if ((new_p - target_p).norm() < 1e-4 && new_q.angle_to(target_q) < 1e-3) {
                return 1;
            }
            return 2;
        }
        return 0;
    };

    int conn_a = -1, conn_b = -1;
    bool swapped = false;

    for (int iter = 0; iter < 100000; ++iter) {
        Vec3 q_rand_p = {dist_x(rng), dist_y(rng), dist_z(rng)};
        Quat q_rand_q = random_quat();

        int new_idx_a = -1;
        if (extend(tree_a, q_rand_p, q_rand_q, new_idx_a) != 0) {
            Vec3 target_p = tree_a[new_idx_a].pos;
            Quat target_q = tree_a[new_idx_a].q;

            int new_idx_b = -1;
            while (true) {
                int status = extend(tree_b, target_p, target_q, new_idx_b);
                if (status == 1) {
                    conn_a = new_idx_a;
                    conn_b = new_idx_b;
                    break;
                }
                if (status == 0) break;
            }

            if (conn_a != -1) {
                std::cout << "SUCCESSFULLY CONNECTED S1 and S2 at iteration " << iter << "!" << std::endl;
                std::cout << "Tree A: " << tree_a.size() << ", Tree B: " << tree_b.size() << std::endl;
                break;
            }
        }

        std::swap(tree_a, tree_b);
        swapped = !swapped;
    }

    if (conn_a != -1) {
        auto& t_start = swapped ? tree_b : tree_a;
        auto& t_goal  = swapped ? tree_a : tree_b;
        int idx_s = swapped ? conn_b : conn_a;
        int idx_g = swapped ? conn_a : conn_b;

        std::vector<Node> bridge;
        int c = idx_s;
        while (c != -1) {
            bridge.push_back(t_start[c]);
            c = t_start[c].parent;
        }
        std::reverse(bridge.begin(), bridge.end());

        c = t_goal[idx_g].parent;
        while (c != -1) {
            bridge.push_back(t_goal[c]);
            c = t_goal[c].parent;
        }

        std::cout << "Bridge length: " << bridge.size() << " waypoints" << std::endl;
        std::ofstream out("/tmp/bridge_s1_s2.txt");
        for (const auto& n : bridge) {
            out << n.pos.x << " " << n.pos.y << " " << n.pos.z << " "
                << n.q.w << " " << n.q.x << " " << n.q.y << " " << n.q.z << "\n";
        }
        std::cout << "Wrote /tmp/bridge_s1_s2.txt" << std::endl;
    } else {
        std::cout << "Could not connect in 100k iterations." << std::endl;
    }

    return 0;
}
