    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    Vec3 operator*(double s) const { return {x * s, y * s, z * s}; }
    double dot(const Vec3& o) const { return x * o.x + y * o.y + z * o.z; }
    double norm_sq() const { return dot(*this); }
    double norm() const { return std::sqrt(norm_sq()); }
};

struct Quat {
    double w, x, y, z;
    static Quat identity() { return {1, 0, 0, 0}; }
    Vec3 rotate(const Vec3& v) const {
        Vec3 r = {x, y, z};
        Vec3 rxv = {r.y * v.z - r.z * v.y, r.z * v.x - r.x * v.z, r.x * v.y - r.y * v.x};
        Vec3 rxv_wv = {rxv.x + w * v.x, rxv.y + w * v.y, rxv.z + w * v.z};
        Vec3 r_rxv_wv = {r.y * rxv_wv.z - r.z * rxv_wv.y, r.z * rxv_wv.x - r.x * rxv_wv.z, r.x * rxv_wv.y - r.y * rxv_wv.x};
        return {v.x + 2.0 * r_rxv_wv.x, v.y + 2.0 * r_rxv_wv.y, v.z + 2.0 * r_rxv_wv.z};
    }
    Quat operator*(const Quat& q) const {
        return {
            w * q.w - x * q.x - y * q.y - z * q.z,
            w * q.x + x * q.w + y * q.z - z * q.y,
            w * q.y - x * q.z + y * q.w + z * q.x,
            w * q.z + x * q.y - y * q.x + z * q.w
        };
    }
    void normalize() {
        double n = std::sqrt(w*w + x*x + y*y + z*z);
        if (n > 1e-12) { w /= n; x /= n; y /= n; z /= n; }
    }
    static Quat slerp(const Quat& q1, const Quat& q2, double t) {
        double dot = q1.w * q2.w + q1.x * q2.x + q1.y * q2.y + q1.z * q2.z;
        Quat q2_mod = q2;
        if (dot < 0.0) {
            dot = -dot;
            q2_mod = {-q2.w, -q2.x, -q2.y, -q2.z};
        }
        if (dot > 0.9995) {
            Quat r = {
                q1.w + t * (q2_mod.w - q1.w),
                q1.x + t * (q2_mod.x - q1.x),
                q1.y + t * (q2_mod.y - q1.y),
                q1.z + t * (q2_mod.z - q1.z)
            };
            r.normalize();
            return r;
        }
        double theta = std::acos(dot);
        double sin_theta = std::sin(theta);
        double s1 = std::sin((1.0 - t) * theta) / sin_theta;
        double s2 = std::sin(t * theta) / sin_theta;
        return {
            s1 * q1.w + s2 * q2_mod.w,
            s1 * q1.x + s2 * q2_mod.x,
            s1 * q1.y + s2 * q2_mod.y,
            s1 * q1.z + s2 * q2_mod.z
        };
    }
    double angle_to(const Quat& o) const {
        double dot = std::abs(w * o.w + x * o.x + y * o.y + z * o.z);
        if (dot > 1.0) dot = 1.0;
        return 2.0 * std::acos(dot);
    }
    static Quat from_axis_angle(const Vec3& axis, double angle) {
        double half = angle * 0.5;
        double s = std::sin(half);
        return {std::cos(half), axis.x * s, axis.y * s, axis.z * s};
    }
};

double dist_sq_segment_to_segment(const Vec3& p1, const Vec3& q1, const Vec3& p2, const Vec3& q2) {
    Vec3 d1 = q1 - p1;
