    Vec3 r = p1 - p2;
    double a = d1.norm_sq();
    double e = d2.norm_sq();
    double f = d2.dot(r);
    double s, t;
    if (a <= 1e-12 && e <= 1e-12) return r.norm_sq();
    if (a <= 1e-12) {
