    std::mt19937_64 rng(42);
    // Search volume: we want to advance y towards 1.80!
    std::uniform_real_distribution<double> dist_x(0.70, 1.30);
    std::uniform_real_distribution<double> dist_y(1.35, 2.00);
    std::uniform_real_distribution<double> dist_z(0.50, 0.90);
    std::normal_distribution<double> dist_norm(0.0, 1.0);
    std::uniform_real_distribution<double> dist_uni(0.0, 1.0);

