        } else {
            target_p = {dist_x(rng), dist_y(rng), dist_z(rng)};
            target_q = random_quat();
        }

        // Nearest neighbor
        int best_i = 0;
        double best_d = 1e9;
        for (int i = 0; i < (int)tree.size(); ++i) {
            double d = (tree[i].pos - target_p).norm() + 0.3 * tree[i].q.angle_to(target_q);
            if (d < best_d) { best_d = d; best_i = i; }
