            std::cout << "Iter " << iter << ", tree size: " << tree.size() << ", elapsed: " << sec << " s" << std::endl;
        }
    }

    if (goal_idx != -1) {
        std::vector<Node> path;
        int curr = goal_idx;
        while (curr != -1) {
            path.push_back(tree[curr]);
            curr = tree[curr].parent;
        }
        std::reverse(path.begin(), path.end());

        std::cout << "SUCCESS! Path length from current state: " << path.size() << " waypoints" << std::endl;
        std::ofstream out("/tmp/finish_path.txt");
