        segs_a[i].p1 = pts_a[i];
        segs_a[i].p2 = pts_a[i+1];
        update_aabb(segs_a[i]);
    }

    Vec3 start_pos = {0.96819, 1.41, 0.65914};
    Quat start_q = {0.35231, -0.51915, -0.77535, -0.07205};

    std::vector<Node> tree;
    tree.push_back({start_pos, start_q, -1});

    std::mt19937_64 rng(42);
    std::uniform_real_distribution<double> dist_x(0.70, 1.30);
    std::uniform_real_distribution<double> dist_y(1.35, 2.00);
    std::uniform_real_distribution<double> dist_z(0.50, 0.90);
    std::normal_distribution<double> dist_norm(0.0, 1.0);
    std::uniform_real_distribution<double> dist_uni(0.0, 1.0);

    auto random_quat = [&]() -> Quat {
        Quat q = {dist_norm(rng), dist_norm(rng), dist_norm(rng), dist_norm(rng)};
        q.normalize();
        return q;
    };

    for (int iter = 0; iter < 50000; ++iter) {
        Vec3 target_p;
        Quat target_q;
        if (dist_uni(rng) < 0.4) {
            target_p = {start_pos.x + 0.05 * dist_norm(rng), 1.80 + 0.2 * dist_uni(rng), start_pos.z + 0.05 * dist_norm(rng)};
            target_q = start_q;
        } else {
            target_p = {dist_x(rng), dist_y(rng), dist_z(rng)};
            target_q = random_quat();
        }

        int best_i = 0;
        double best_d = 1e9;
        for (int i = 0; i < (int)tree.size(); ++i) {
            double d = (tree[i].pos - target_p).norm() + 0.3 * tree[i].q.angle_to(target_q);
            if (d < best_d) { best_d = d; best_i = i; }
        }

        const Node& near_n = tree[best_i];
        Vec3 dp = target_p - near_n.pos;
        double ndp = dp.norm();
        double step_p = 0.02;
        Vec3 new_p = (ndp <= step_p) ? target_p : (near_n.pos + dp * (step_p / ndp));

        double da = near_n.q.angle_to(target_q);
        double step_r = 0.04;
        Quat new_q = (da <= step_r) ? target_q : Quat::slerp(near_n.q, target_q, step_r / da);

        if (is_collision_free((near_n.pos + new_p) * 0.5, Quat::slerp(near_n.q, new_q, 0.5)) &&
            is_collision_free(new_p, new_q)) {
            int new_idx = tree.size();
            tree.push_back({new_p, new_q, best_i});
        }
    }

    std::ofstream out("/tmp/tree_sim.bin", std::ios::binary);
    size_t sz = tree.size();
    out.write(reinterpret_cast<char*>(&sz), sizeof(size_t));
    for (const auto& n : tree) {
        out.write(reinterpret_cast<const char*>(&n.pos), sizeof(Vec3));
        out.write(reinterpret_cast<const char*>(&n.q), sizeof(Quat));
        out.write(reinterpret_cast<const char*>(&n.parent), sizeof(int));
    }
    std::cout << "Saved " << sz << " nodes to /tmp/tree_sim.bin" << std::endl;
    return 0;
}
